import{_ as e,o as t,c as r,a5 as a}from"./chunks/framework.CnBNXlt7.js";const m=JSON.parse('{"title":"2025/06/26","description":"","frontmatter":{},"headers":[],"relativePath":"trip/journey/20250626.md","filePath":"trip/journey/20250626.md","lastUpdated":1752144819000}'),o={name:"trip/journey/20250626.md"};function _(n,p,s,i,d,c){return t(),r("div",null,[...p[0]||(p[0]=[a('<h1 id="_2025-06-26" tabindex="-1">2025/06/26 <a class="header-anchor" href="#_2025-06-26" aria-label="Permalink to &quot;2025/06/26&quot;">​</a></h1><p>原计划<br> 20:05-22:10</p><p>大风大雨伴有雷声，看了天气，机场似乎无雨。</p><p>公交车硬是吃满红绿灯，走了10分钟，完全耽误事，17:40才到地铁站。</p><p>18:05 文三路19号线抵达，18:42机场站抵达。<br> 每次19号线从钱塘江上，一直到耕文路站都是没有网络。<br> 一路快走，没停，18:50抵达北贵宾厅。</p><p>很快办完手续，去食堂。这次工作人员没有19:00准时收走自助餐，让大家继续吃。但是，今天没什么胃口。随便吃了一点，就很想喝水。这次去建行贵宾厅。</p><p>喝了一瓶雪碧，一瓶海南椰汁，一瓶王老吉。</p><p>期间19:40左右，有京爷被告知前往北京的航班提前一个小时登机。京爷震惊不是20:30登机吗。</p><p>没想到在贵宾厅，眼睁睁看着不停的晚点。<br> 从20:05到20:40，再到21:06。好在，20:05提醒登机，没想到啊，贵宾厅安检也拥堵了。<br> 排队过程中，看到来了一批安检工作人员，加开了一个通道。缓解了不小的压力。<br> 但是过完安检，贵宾车人力不够，继续等待少许。</p><p>由于此趟航班摆渡车登机，来登机口接头等舱，但是等了10多分钟，20:35工作人员过来招呼我们这趟车先去登机。</p><p>摆渡车登机，一批接一批，慢慢悠悠，20:44登机结束。继续延误，21:22起飞。</p><p>21:05广播: 因为机场雷雨，飞机挤压，无法起飞。</p><p>21:23才推出。一直滑呀滑，21:59前一个顺丰货机飞走。终于要飞了……</p>',13)])])}const u=e(o,[["render",_]]);export{m as __pageData,u as default};
